def calc_equation(equations, values, queries):
    graph = defaultdict(dict)
    for (a, b), k in zip(equations, values):
        graph[a][b] = k
        graph[b][a] = 1 / k

    def solve(x, y):
        if x not in graph or y not in graph:
            return -1.0
        seen, stack = {x}, [(x, 1.0)]
        while stack:
            node, prod = stack.pop()
            if node == y:
                return prod
            for nb, w in graph[node].items():
                if nb not in seen:
                    seen.add(nb); stack.append((nb, prod * w))
        return -1.0

    return [solve(x, y) for x, y in queries]

def calc_equation(equations, values, queries):
    parent, weight = {}, {}

    def find(x):
        if parent[x] != x:
            root = find(parent[x])
            weight[x] *= weight[parent[x]]         # x / root
            parent[x] = root
        return parent[x]

    for (a, b), k in zip(equations, values):
        for v in (a, b):
            if v not in parent:
                parent[v], weight[v] = v, 1.0
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            weight[ra] = k * weight[b] / weight[a]  # makes a / b == k

    out = []
    for x, y in queries:
        if x not in parent or y not in parent or find(x) != find(y):
            out.append(-1.0)
        else:
            out.append(weight[x] / weight[y])
    return out
